head.script:
scwin.onpageload = function() {

};

scwin.trigger1_onclick = function(e) {
    var obj = {
        "title" : "Test"+String(Math.random()).substring(2), 
        "windowID": "win"+String(Math.random()).substring(2), 
        "frameMode" : "wframe", 
        "src" : "/test/windowContainer/sample4/test2.xml",
       // openAction : "selectWindow"
        };
    $p.top().wdc_main.createWindow(obj);
    //WebSquare.event.stopPropagation(e);
};

scwin.trigger2_onclick = function(e) {
    $p.executeSubmission( "submission1" );
};

scwin.submission1_submitdone = function(e) {
        var obj = {
        "title" : "Test"+String(Math.random()).substring(2), 
        "windowID": "win"+String(Math.random()).substring(2), 
        "frameMode" : "wframe", 
        "src" : "/test/windowContainer/sample4/test2.xml",
       // openAction : "selectWindow"
        };
    $p.top().wdc_main.createWindow(obj); 
};

scwin.trigger3_onclick = function(e) {
        var options = {  
        id : "popup"+String(Math.random()).substring(2), 
        type : "browserPopup", 
        width: "230px", 
        height: "250px", 
        popupName : "팝업 예제", 
        modal : false,
        useMaximize : false,
        useControl : true,
        frameModal : "frame",
        controls : { minimize: true, maximize: true, close: true }
    }; 
    $p.openPopup("windowContainer_frameModal_WESE-967_(WSQ-5826)_popup.xml", options);
};

scwin.trigger4_onclick = function(e) {
    var options = {  
        id : "popup"+String(Math.random()).substring(2), 
        type : "wframePopup", 
        width: "230px", 
        height: "250px", 
        popupName : "팝업 예제", 
        modal : true,
        useMaximize : false,
        useControl : true,
        resizable : true,
        frameModal : "frame",
        alwaysOnTop : true,
        controls : { minimize: true, maximize: true, close: true }
    }; 
    $p.openPopup("windowContainer_frameModal_WESE-967_(WSQ-5826)_popup.xml", options);
};
